-- ----------------------------
-- Table structure for table small_cell_param
-- ----------------------------
DROP TABLE IF EXISTS `small_cell_param`;
CREATE TABLE `small_cell_param` (
  `PARAM_ID` bigint NOT NULL COMMENT '参数ID，通过解析程序生成数据时生成',
  `PARAM_NAME` varchar(255) NOT NULL COMMENT '参数英文名称',
  `NAME_PATH` varchar(255) NOT NULL,
  `DFT_VALUE` varchar(4000) DEFAULT NULL COMMENT '参数默认值',
  `V_TYPE` text COMMENT '取值类型，描述与取值相关的所有信息，以字符串形式',
  `V_WRITABLE` varchar(10) DEFAULT NULL COMMENT '0-不可操作  1-可操作',
  `V_LST` char(2) DEFAULT 'N' COMMENT '是否立即显示 Y是，N否',
  `V_MOD` char(2) DEFAULT 'N' COMMENT '是否可以修改 Y是，N否',
  `V_ADD` char(2) DEFAULT 'N' COMMENT '是否可以添加 Y是，N否',
  `V_RMV` char(2) DEFAULT 'N' COMMENT '是否可以删除 Y是，N否',
  `IS_LEAF` char(1) DEFAULT NULL COMMENT '是否末级  Y是 ，N否 ',
  `DISP_ORD` decimal(8,0) DEFAULT '0' COMMENT '顺序',
  `STOP_SIGN` char(1) NOT NULL DEFAULT '0' COMMENT '0：使用中 1：停用',
  `MEMO` text COMMENT '描述',
  `V_DYNAMIC` char(2) DEFAULT NULL COMMENT '参数是否动态生效，即设置完该参数后是否需要重启小站',
  `PARAM_VERSION` varchar(45) NOT NULL COMMENT '参数版本，参数版本对应多个软件版本号',
  `MIB_DN` varchar(100) DEFAULT NULL,
  `PARAM_NAME_EN` varchar(255) DEFAULT '' COMMENT '参数英文名称',
  `MOBILE_SUPPORT` char(4) DEFAULT 'Y' COMMENT '移动版支持配置，Y --支持，N--不支持',
  `BROADBAND_SUPPORT` char(4) DEFAULT 'Y' COMMENT '宽带版支持配置，Y --支持，N--不支持',
  `JS_REGEX` varchar(500) DEFAULT NULL,
  `TITLE_CN` varchar(1000) DEFAULT NULL,
  `TITLE_EN` varchar(1000) DEFAULT NULL,
  `PLATFORM_SUPPORT` varchar(5) DEFAULT NULL,
  `CN_EXPLANATION` varchar(1000) DEFAULT NULL COMMENT '参数中文解释说明',
  `EN_EXPLANATION` varchar(1000) DEFAULT NULL COMMENT '参数英文解释说明',
  `SOFTWARE_VERSION` varchar(100) DEFAULT NULL COMMENT '基站软件版本号',
  `second_confirm` char(1) DEFAULT NULL,
  `confirm_en` varchar(1000) DEFAULT NULL,
  `confirm_cn` varchar(1000) DEFAULT NULL,
  PRIMARY KEY (`PARAM_ID`),
  UNIQUE KEY `PATHVERSION` (`NAME_PATH`,`PARAM_VERSION`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 AVG_ROW_LENGTH=304 COMMENT='小站系统参数表';

