INSERT INTO `small_cell_param` (`PARAM_ID`,`PARAM_NAME`,`NAME_PATH`,`DFT_VALUE`,`V_TYPE`,`V_WRITABLE`,`V_LST`,`V_MOD`,`V_ADD`,`V_RMV`,`IS_LEAF`,`DISP_ORD`,`STOP_SIGN`,`MEMO`,`V_DYNAMIC`,`PARAM_VERSION`,`MIB_DN`,`PARAM_NAME_EN`,`MOBILE_SUPPORT`,`BROADBAND_SUPPORT`,`JS_REGEX`,`TITLE_CN`,`TITLE_EN`,`PLATFORM_SUPPORT`,`CN_EXPLANATION`,`EN_EXPLANATION`,`SOFTWARE_VERSION`,`second_confirm`,`confirm_en`,`confirm_cn`)  VALUES ('4081','基站名称','Device.Services.FAPService.{i}.AccessMgmt.LTE.HNBName','','string-[0:48]','-','N','Y','N','N','Y',0,'0',NULL,'0','436Q1.0','LTE_HOME_NODEB_NAME','Cell Name','Y','Y','/^\\w+$/','字母、数字、下划线，长度：0-48','Alphanumeric underscore,length:0-48','2','用户友好名，由EMS厂商自己指定，作为其内部标识，并可被NMS修改。要求UserLabel与告警、性能数据中同一小区对象使用的网元用户友好名保持一致，即用户有好名在北向接口交互过程中全局唯一。','The user-friendly name, which is specified by the EMS manufacturer itself and can be modified by NMS. The UserLabel must be consistent with the user-friendly name of the same community object in the alarm and performance data, that is, the user has a good name that is globally unique during North interface interaction.',NULL,NULL,NULL,NULL);
INSERT INTO `small_cell_param` (`PARAM_ID`,`PARAM_NAME`,`NAME_PATH`,`DFT_VALUE`,`V_TYPE`,`V_WRITABLE`,`V_LST`,`V_MOD`,`V_ADD`,`V_RMV`,`IS_LEAF`,`DISP_ORD`,`STOP_SIGN`,`MEMO`,`V_DYNAMIC`,`PARAM_VERSION`,`MIB_DN`,`PARAM_NAME_EN`,`MOBILE_SUPPORT`,`BROADBAND_SUPPORT`,`JS_REGEX`,`TITLE_CN`,`TITLE_EN`,`PLATFORM_SUPPORT`,`CN_EXPLANATION`,`EN_EXPLANATION`,`SOFTWARE_VERSION`,`second_confirm`,`confirm_en`,`confirm_cn`)  VALUES ('4082','跟踪区码','Device.Services.FAPService.{i}.CellConfig.LTE.EPC.TAC','','unsignedInt-[0:65535]','-','N','Y','N','N','Y',0,'0',NULL,'0','436Q1.0','LTE_TAC','TAC','Y','Y','','整数，范围：0-65535','Integer,range:0-65535','2','PLMN网络的公用跟踪区码（0-65535）。该标识用于跟踪区域。一个小区最多能有1个跟踪区码。','The public tracing area code of the PLMN Network (0-65535). This identifier is used to track regions. A community can have a maximum of one tracking area code.',NULL,NULL,NULL,NULL);
