INSERT INTO `small_cell_param` (`PARAM_ID`,`PARAM_NAME`,`NAME_PATH`,`DFT_VALUE`,`V_TYPE`,`V_WRITABLE`,`V_LST`,`V_MOD`,`V_ADD`,`V_RMV`,`IS_LEAF`,`DISP_ORD`,`STOP_SIGN`,`MEMO`,`V_DYNAMIC`,`PARAM_VERSION`,`MIB_DN`,`PARAM_NAME_EN`,`MOBILE_SUPPORT`,`BROADBAND_SUPPORT`,`JS_REGEX`,`TITLE_CN`,`TITLE_EN`,`PLATFORM_SUPPORT`,`CN_EXPLANATION`,`EN_EXPLANATION`,`SOFTWARE_VERSION`,`second_confirm`,`confirm_en`,`confirm_cn`)  VALUES ('4082000','跟踪区码','Device.Services.FAPService.{i}.CellConfig.LTE.EPC.TAC','','unsignedInt-[0:65535]','-','N','Y','N','N','Y',0,'0',NULL,'0','BAIBLQ1.0','LTE_TAC','TAC','Y','Y','','整数，范围：0-65535','Integer,range:0-65535','2','PLMN网络的公用跟踪区码（0-65535）。该标识用于跟踪区域。一个小区最多能有1个跟踪区码。','The public tracing area code of the PLMN Network (0-65535). This identifier is used to track regions. A community can have a maximum of one tracking area code.',NULL,NULL,NULL,NULL);
