INSERT INTO `small_cell_param` (`PARAM_ID`,`PARAM_NAME`,`NAME_PATH`,`DFT_VALUE`,`V_TYPE`,`V_WRITABLE`,`V_LST`,`V_MOD`,`V_ADD`,`V_RMV`,`IS_LEAF`,`DISP_ORD`,`STOP_SIGN`,`MEMO`,`V_DYNAMIC`,`PARAM_VERSION`,`MIB_DN`,`PARAM_NAME_EN`,`MOBILE_SUPPORT`,`BROADBAND_SUPPORT`,`JS_REGEX`,`TITLE_CN`,`TITLE_EN`,`PLATFORM_SUPPORT`,`CN_EXPLANATION`,`EN_EXPLANATION`,`SOFTWARE_VERSION`,`second_confirm`,`confirm_en`,`confirm_cn`)  VALUES ('4346078','PLMN RAT Priority List','Device.Services.FAPService.{i}.X_RADISYS.COM.LTE.CSFB.PLMNRATPriotityList','','string-[0:200]','-','N','Y','N','N','Y',0,'0',NULL,'0','MLQ1.0','PLMN_RAT_PRIORITY_LIST','PLMN RAT Priority List','Y','Y','','填入整数0、2或10。如果基站中有多个PLMN设置CSFB优先级，则可以输入以逗号分隔的0、2、10的组合，以表示每个PLMN优先回落到的网络。其中0是UMTS， 2是GSM， 10是null。例如，填写2,10,0，代表PLMN1优先回落到GSM，PLMN2不设置优先级，PLMN3优先回落到UMTS。','Fill in the integers 0, 2 or 10. If there are multiple PLMNS in the base station with CSFB priorities set, a comma-separated combination of 0, 2, and 10 can be entered to represent the network to which each PLMN falls back first. Among them, 0 is UMTS, 2 is GSM, and 10 is null. For example, filling in 2,10,0 indicates that PLMN1 is preferentially dropped back to GSM, PLMN2 has no priority set, and PLMN3 is preferentially dropped back to UMTS.','',NULL,NULL,NULL,NULL,NULL,NULL);
